create table BIDDUIDDETAILS (
   DUID                 VARCHAR(10)          not null,
   EFFECTIVEDATE        TIMESTAMP(0)         not null,
   VERSIONNO            NUMERIC(3,0)         not null,
   BIDTYPE              VARCHAR(10)          not null,
