   add constraint FPP_UNIT_MW_PK primary key (INTERVAL_DATETIME, MEASUREMENT_DATETIME, FPP_UNITID, VERSIONNO);

/*==============================================================*/
/* Table: FPP_USAGE                                             */
/*==============================================================*/
create table FPP_USAGE (
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   CONSTRAINTID         VARCHAR(20)          not null,
   VERSIONNO            NUMERIC(5)           not null,
   BIDTYPE              VARCHAR(10)          null,
   REGULATION_MW        NUMERIC(18,8)        null,
   USED_MW              NUMERIC(18,8)        null,
   USAGE_VALUE          NUMERIC(18,8)        null,
