   GENCONID             VARCHAR(20)          not null,
   EFFECTIVEDATE        TIMESTAMP(0)         not null,
   VERSIONNO            NUMERIC(22,0)        not null,
   SCOPE                VARCHAR(2)           not null,
   TERMID               NUMERIC(4,0)         not null,
   GROUPID              NUMERIC(3,0)         null,
   SPD_ID               VARCHAR(21)          null,
