   FORECAST_RUN_DATETIME TIMESTAMP(0)         not null,
   DUID                 VARCHAR(20)          not null,
   OFFERDATETIME        TIMESTAMP(0)         not null,
   PROVIDERID           VARCHAR(20)          not null,
   FORECAST_PRIORITY    NUMERIC(10,0)        not null,
