/*==============================================================*/
/* Table: PD7DAY_CONSTRAINTSOLUTION                             */
/*==============================================================*/
create table PD7DAY_CONSTRAINTSOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   INTERVENTION         NUMERIC(2,0)         not null,
