/*==============================================================*/
/* Table: PDPASA_CASESOLUTION                                   */
/*==============================================================*/
create table PDPASA_CASESOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   PASAVERSION          VARCHAR(10)          null,
   RESERVECONDITION     NUMERIC(1,0)         null,
   LORCONDITION         NUMERIC(1,0)         null,
   CAPACITYOBJFUNCTION  NUMERIC(12,3)        null,
   CAPACITYOPTION       NUMERIC(12,3)        null,
   MAXSURPLUSRESERVEOPTION NUMERIC(12,3)        null,
   MAXSPARECAPACITYOPTION NUMERIC(12,3)        null,
   INTERCONNECTORFLOWPENALTY NUMERIC(12,3)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   RELIABILITYLRCDEMANDOPTION NUMERIC(12,3)        null,
   OUTAGELRCDEMANDOPTION NUMERIC(12,3)        null,
   LORDEMANDOPTION      NUMERIC(12,3)        null,
   RELIABILITYLRCCAPACITYOPTION VARCHAR(10)          null,
   OUTAGELRCCAPACITYOPTION VARCHAR(10)          null,
   LORCAPACITYOPTION    VARCHAR(10)          null,
   LORUIGFOPTION        NUMERIC(3,0)         null,
   RELIABILITYLRCUIGFOPTION NUMERIC(3,0)         null,
   OUTAGELRCUIGFOPTION  NUMERIC(3,0)         null
);

comment on table PDPASA_CASESOLUTION is
'The top-level table identifying a PDPASA case, reporting options applied in the case and summary results';

comment on column PDPASA_CASESOLUTION.RUN_DATETIME is
'Case identifier by the time the case was run';

comment on column PDPASA_CASESOLUTION.PASAVERSION is
'Version of the PASA solver used to solve this case';

comment on column PDPASA_CASESOLUTION.RESERVECONDITION is
'Low Reserve Condition (LRC) flag for the case (1 - LRC in the case, 0 - No LRCs in the case) for capacity run';

comment on column PDPASA_CASESOLUTION.LORCONDITION is
'Lack of Reserve Condition (LOR) flag for the case indicates the most severe condition in the case  (3 = LOR3, 2 = LOR2, 1 = LOR1, 0 = No LOR)';

comment on column PDPASA_CASESOLUTION.CAPACITYOBJFUNCTION is
'Objective Function from the Capacity Adequacy run';

comment on column PDPASA_CASESOLUTION.CAPACITYOPTION is
'Not populated as of 2005 End of Year Release; was the Probability of Exceedance (POE) demand forecast used for capacity adequacy (LRC) assessment. 0 if no assessment, 1 for 10% POE, 2 for 50% POE, 3 for 90% POE.';

comment on column PDPASA_CASESOLUTION.MAXSURPLUSRESERVEOPTION is
'Not populated as of 2005 End of Year Release; was the Probability of Exceedance (POE) demand forecast used for assessment of Maximum surplus Reserve. 0 if no assessment, 1 for 10% POE, 2 for 50% POE, 3 for 90% POE';

comment on column PDPASA_CASESOLUTION.MAXSPARECAPACITYOPTION is
'Not populated as of 2005 End of Year Release; was the Probability of Exceedance (POE) demand forecast used for assessment of Maximum Spare Capacity. 0 if no assessment, 1 for 10% POE, 2 for 50% POE, 3 for 90% POE';

comment on column PDPASA_CASESOLUTION.INTERCONNECTORFLOWPENALTY is
'The penalty for non-zero interconnector flow';

comment on column PDPASA_CASESOLUTION.LASTCHANGED is
'Date and time the record was created or modified';

comment on column PDPASA_CASESOLUTION.RELIABILITYLRCDEMANDOPTION is
'Specifies the Probability of Exceedence (POE) demand forecast for Reliability LRC assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)';

comment on column PDPASA_CASESOLUTION.OUTAGELRCDEMANDOPTION is
'Specifies the Probability of Exceedence (POE) demand forecast for outage LRC assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)';

comment on column PDPASA_CASESOLUTION.LORDEMANDOPTION is
'Specifies the Probability of Exceedence (POE) demand forecast for LOR assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)';

comment on column PDPASA_CASESOLUTION.RELIABILITYLRCCAPACITYOPTION is
'Generation Availability to be used in Reliability LRC run (either PASA or MARKET)';

comment on column PDPASA_CASESOLUTION.OUTAGELRCCAPACITYOPTION is
'Generation Availability to be used in Outage LRC run (either PASA or MARKET)';

comment on column PDPASA_CASESOLUTION.LORCAPACITYOPTION is
'Generation Availability to be used in LOR run (either PASA or MARKET)';

comment on column PDPASA_CASESOLUTION.LORUIGFOPTION is
'UIGF POE forecast availability used for this option';

comment on column PDPASA_CASESOLUTION.RELIABILITYLRCUIGFOPTION is
'UIGF POE forecast availability used for this option';

comment on column PDPASA_CASESOLUTION.OUTAGELRCUIGFOPTION is
'UIGF POE forecast availability used for this option';

alter table PDPASA_CASESOLUTION
   add constraint PDPASA_CASESOLUTION_PK primary key (RUN_DATETIME);

/*==============================================================*/
/* Index: PDPASA_CASESOLUTION_LCX                               */
/*==============================================================*/
create  index PDPASA_CASESOLUTION_LCX on PDPASA_CASESOLUTION (
LASTCHANGED
);

/*==============================================================*/
/* Table: PDPASA_CONSTRAINTSOLUTION                             */
/*==============================================================*/
create table PDPASA_CONSTRAINTSOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   CONSTRAINTID         VARCHAR(20)          not null,
   CAPACITYRHS          NUMERIC(12,2)        null,
   CAPACITYMARGINALVALUE NUMERIC(12,2)        null,
   CAPACITYVIOLATIONDEGREE NUMERIC(12,2)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   RUNTYPE              VARCHAR(20)          not null default 'OUTAGE_LRC',
   STUDYREGIONID        VARCHAR(20)          not null default 'MARKET'
);

comment on table PDPASA_CONSTRAINTSOLUTION is
'PDPASA_CONSTRAINTSOLUTION shows binding and violated constraint results from the capacity evaluation, including the RHS value.';

comment on column PDPASA_CONSTRAINTSOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this study';

comment on column PDPASA_CONSTRAINTSOLUTION.INTERVAL_DATETIME is
'The unique identifier for the interval within this study';

comment on column PDPASA_CONSTRAINTSOLUTION.CONSTRAINTID is
'Constraint identifier (synonymous with GenConID)';

comment on column PDPASA_CONSTRAINTSOLUTION.CAPACITYRHS is
'The RHS value in the capacity evaluation.';

comment on column PDPASA_CONSTRAINTSOLUTION.CAPACITYMARGINALVALUE is
'Capacity adequacy assessment marginal value, 0 if not binding';

comment on column PDPASA_CONSTRAINTSOLUTION.CAPACITYVIOLATIONDEGREE is
'Capacity adequacy assessment violation degree for generic constraint; 0 if not violating';

comment on column PDPASA_CONSTRAINTSOLUTION.LASTCHANGED is
'Last changed date of this record';

comment on column PDPASA_CONSTRAINTSOLUTION.RUNTYPE is
'Type of run. Values are OUTAGE_LRC and LOR. Note that the PDPASA OUTAGE_LRC Run Type is discontinued from 31 July 2025, with only the LOR Run Type reported.';

comment on column PDPASA_CONSTRAINTSOLUTION.STUDYREGIONID is
'Primary Region for LP Solve (or MARKET if none).';

alter table PDPASA_CONSTRAINTSOLUTION
   add constraint PDPASA_CONSTRAINTSOLUTION_PK primary key (RUN_DATETIME, RUNTYPE, INTERVAL_DATETIME, CONSTRAINTID, STUDYREGIONID);

/*==============================================================*/
/* Table: PDPASA_DUIDAVAILABILITY                               */
/*==============================================================*/
create table PDPASA_DUIDAVAILABILITY (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   DUID                 VARCHAR(20)          not null,
   GENERATION_MAX_AVAILABILITY NUMERIC(12,6)        null,
   GENERATION_PASA_AVAILABILITY NUMERIC(12,0)        null,
   GENERATION_RECALL_PERIOD NUMERIC(8,3)         null,
   LOAD_MAX_AVAILABILITY NUMERIC(12,6)        null,
   LOAD_PASA_AVAILABILITY NUMERIC(12,0)        null,
   LOAD_RECALL_PERIOD   NUMERIC(8,3)         null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table PDPASA_DUIDAVAILABILITY is
'This report delivers available capacity, PASA availability and given recall period for all scheduled resources. Note that for an MNSP, DUID = LINKID in the MNSP_INTERCONNECTOR table.';

comment on column PDPASA_DUIDAVAILABILITY.RUN_DATETIME is
'PDPASA run, identified by the first half hour ended interval of the run.';

comment on column PDPASA_DUIDAVAILABILITY.INTERVAL_DATETIME is
'Half hour ended interval';

comment on column PDPASA_DUIDAVAILABILITY.DUID is
'NEM Dispatchable Unit Identifier';

comment on column PDPASA_DUIDAVAILABILITY.GENERATION_MAX_AVAILABILITY is
'Available Capacity for a scheduled generating unit, semi-scheduled generating unit, BDU (Gen side), WDR or MNSP.';

comment on column PDPASA_DUIDAVAILABILITY.GENERATION_PASA_AVAILABILITY is
'PASA Availability for a scheduled generating unit, BDU (Gen side), WDR or MNSP. Null for a semi-scheduled generating unit.';

comment on column PDPASA_DUIDAVAILABILITY.GENERATION_RECALL_PERIOD is
'Recall Period associated with the PASA Availability for a scheduled generating unit, BDU (Gen side), WDR or MNSP. Null for a semi-scheduled generating unit.';

comment on column PDPASA_DUIDAVAILABILITY.LOAD_MAX_AVAILABILITY is
'Available Capacity for a scheduled load or BDU(Load side).';

comment on column PDPASA_DUIDAVAILABILITY.LOAD_PASA_AVAILABILITY is
'PASA Availability for a scheduled load or BDU(Load side).';

comment on column PDPASA_DUIDAVAILABILITY.LOAD_RECALL_PERIOD is
'Recall Period associated with the PASA Availability for a scheduled load or BDU(Load side).';

comment on column PDPASA_DUIDAVAILABILITY.LASTCHANGED is
'Report Creation Date Time.';

alter table PDPASA_DUIDAVAILABILITY
   add constraint PDPASA_DUIDAVAILABILITY_PK primary key (RUN_DATETIME, INTERVAL_DATETIME, DUID);

/*==============================================================*/
/* Table: PDPASA_FNM_CASESOLUTION                               */
/*==============================================================*/
create table PDPASA_FNM_CASESOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   LORCONDITION         NUMERIC(1,0)         null,
   DEFICITCONDITION     NUMERIC(1,0)         null,
   BASE_RUN_AVAILABLE   VARCHAR(10)          null,
   RELIABILITY_RUN_AVAILABLE VARCHAR(10)          null,
   WARNING_RUN_AVAILABLE VARCHAR(10)          null,
   PASAVERSION          VARCHAR(30)          null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table PDPASA_FNM_CASESOLUTION is
'PDPASA_FNM_CASESOLUTION shows the case run details, including the available run types, LOR and Deficit condition for each case.';

comment on column PDPASA_FNM_CASESOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this run, identified by the first half hour ended interval of the run';

comment on column PDPASA_FNM_CASESOLUTION.LORCONDITION is
'LORCONDITION is only set if supply deficit exists in a Zone that contains the Regional Reference Node. LORCONDITION indicates the most severe condition for the case:
LORCONDITION = 3 if deficit in BASE run, else = 2 if deficit in RELIABILITY run, else = 1 if deficit in WARNING run, else 0';

comment on column PDPASA_FNM_CASESOLUTION.DEFICITCONDITION is
'DEFICITCONDITION is only set if supply deficit exists in a Zone that does NOT contain the Regional Reference Node. DEFICITCONDITION indicates the most severe condition for the case:
DEFICITCONDITION = 3 if deficit in BASE run, else = 2 if deficit in RELIABILITY run, else = 1 if deficit in WARNING run, else 0';

comment on column PDPASA_FNM_CASESOLUTION.BASE_RUN_AVAILABLE is
'YES = Available, NO = Not Available';

comment on column PDPASA_FNM_CASESOLUTION.RELIABILITY_RUN_AVAILABLE is
'YES = Available, NO = Not Available';

comment on column PDPASA_FNM_CASESOLUTION.WARNING_RUN_AVAILABLE is
'YES = Available, NO = Not Available';

comment on column PDPASA_FNM_CASESOLUTION.PASAVERSION is
'Version of the PASA solver used to solve this case';

comment on column PDPASA_FNM_CASESOLUTION.LASTCHANGED is
'Date time this record was created';

alter table PDPASA_FNM_CASESOLUTION
   add constraint PDPASA_FNM_CASESOLUTION_PK primary key (RUN_DATETIME);

