alter table PDPASA_FNM_CONSTRAINTSOLUTION
   add constraint PDPASA_FNM_CONSTRAINTS_PK primary key (RUN_DATETIME, RUNTYPE, INTERVAL_DATETIME, CONSTRAINTID);

