   ENERGYCONSTRAINED_CLEARED NUMERIC(12,2)        null,
   BDU_CLEARED          NUMERIC(12,2)        null,
   SS_CLEARED           NUMERIC(12,2)        null,
   SS_SOLAR_CLEARED     NUMERIC(12,2)        null,
