   CLEAREDLOSSES        NUMERIC(12,2)        null,
   CLEAREDNETINTERCHANGE NUMERIC(12,2)        null,
   CLEAREDDEMAND        NUMERIC(12,2)        null,
   SUPPLYDEFICIT        NUMERIC(12,2)        null,
   SUPPLYDEFICIT_RRN    NUMERIC(12,2)        null,
   SUPPLYDEFICIT_NONRRN NUMERIC(12,2)        null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table PDPASA_FNM_REGIONSOLUTION is
'PDPASA_FNM_REGIONSOLUTION shows region demand, cleared values of resources, spare capacity, losses for each run type and intervals.';

comment on column PDPASA_FNM_REGIONSOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this run, identified by the first half hour ended interval of the run';

comment on column PDPASA_FNM_REGIONSOLUTION.RUNTYPE is
'Run Type (BASE, RELIABILITY, WARNING)';

comment on column PDPASA_FNM_REGIONSOLUTION.INTERVAL_DATETIME is
'End date time of the interval';

comment on column PDPASA_FNM_REGIONSOLUTION.REGIONID is
'Region Identifier';

comment on column PDPASA_FNM_REGIONSOLUTION.LORCONDITION is
'Lack of Reserve Condition (LORCONDITION) > 0 if a supply deficit exists in the Zone for this Region that contains its Regional Reference Node
LORCONDITION = 3 if deficit in BASE run
LORCONDITION = 2 if deficit in RELIABILITY run
LORCONDITION = 1 if deficit in WARNING run';

comment on column PDPASA_FNM_REGIONSOLUTION.DEFICITCONDITION is
'Deficit Condition (DEFICITCONDITION) > 0 if a supply deficit only exists in a Zone for this Region that does not contain its Regional Reference Node
DEFICITCONDITION = 3 if deficit in BASE run
DEFICITCONDITION = 2 if deficit in RELIABILITY run
DEFICITCONDITION = 1 if deficit in WARNING run';

comment on column PDPASA_FNM_REGIONSOLUTION.INITIALDEMAND is
'Most probable Demand Forecast adjusted by Demand Uncertainty Margin (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.DEMAND_UNCERTAINTY_MARGIN is
'Aggregate Uncertainty Margin adjustment to most probable Demand Forecast (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SCHED_GEN_UNCERTAINTY_MARGIN is
'Aggregate Uncertainty Margin adjustment to Scheduled Generation Bid Max Avail (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.VRE_GEN_UNCERTAINTY_MARGIN is
'Aggregate Uncertainty Margin adjustment to most probable VRE Forecast (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SCHED_GEN_AUX_LOAD is
'Aggregate Auxiliary Load adjustment to uncertainty-adjusted Bid MaxAvail of all scheduled generating units (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.ENERGYUNCONSTRAINED_CLEARED is
'Cleared Generation from non energy-constrained resources - that is, excluding bidirectional units and generating units subject to daily energy limits (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.ENERGYCONSTRAINED_CLEARED is
'Cleared Generation from energy-constrained resources - that is, from bidirectional units and generating units subject to daily energy limits (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.BDU_CLEARED is
'Cleared Generation (positive) or Consumption (negative) from bidirectional units (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SS_CLEARED is
'Cleared Generation from semi-scheduled generating units (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SS_SOLAR_CLEARED is
'Cleared Generation from semi-scheduled solar generating units (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SS_WIND_CLEARED is
'Cleared Generation from semi-scheduled wind generating units (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SPARECAPACITY is
'Spare Generation Capacity = max(0, Available Generation minus [Cleared Generation minus Cleared Net Interchange]) (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.CLEAREDSUPPLY is
'Cleared Generation (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.CLEAREDLOSSES is
'Cleared Grid Losses (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.CLEAREDNETINTERCHANGE is
'Cleared Net Export (positive) or Net Import (negative) (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.CLEAREDDEMAND is
'Cleared Demand (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SUPPLYDEFICIT is
'Supply Deficit (MW) across at all loads in the Region = Max(0, Initial Demand minus Cleared Demand) where Cleared Demand = (Cleared Generation minus Cleared Losses minus Cleared Net Interchange).
Supply Deficit = Supply Deficit_RRN + Supply Deficit_NonRRN';

comment on column PDPASA_FNM_REGIONSOLUTION.SUPPLYDEFICIT_RRN is
'Supply Deficit across all loads in the Zone that contains the Regional Reference Node (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.SUPPLYDEFICIT_NONRRN is
'Supply Deficit across all loads in the Zone(s) that do not contain the Regional Reference Node (MW)';

comment on column PDPASA_FNM_REGIONSOLUTION.LASTCHANGED is
'Date time this record was created';

alter table PDPASA_FNM_REGIONSOLUTION
   add constraint PDPASA_FNM_REGIONSOLUTION_PK primary key (RUN_DATETIME, RUNTYPE, INTERVAL_DATETIME, REGIONID);

/*==============================================================*/
/* Table: PDPASA_FNM_REGIONSUMMARY                              */
/*==============================================================*/
create table PDPASA_FNM_REGIONSUMMARY (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   REGIONID             VARCHAR(20)          not null,
   LORCONDITION         NUMERIC(1,0)         null,
   DEFICITCONDITION     NUMERIC(1,0)         null,
   DEMAND50             NUMERIC(12,2)        null,
   DEMAND50_UNSCHED_GEN NUMERIC(12,2)        null,
   SCHED_SS_GEN_CAPACITYAVAIL NUMERIC(12,2)        null,
   UNSCHED_GEN_CAPACITYAVAIL NUMERIC(12,2)        null,
   SCHED_SS_GEN_PASAAVAIL NUMERIC(12,2)        null,
   SCHED_LOAD_CAPACITYAVAIL NUMERIC(12,2)        null,
   SS_UIGF              NUMERIC(12,2)        null,
   SS_SOLAR_UIGF        NUMERIC(12,2)        null,
   SS_WIND_UIGF         NUMERIC(12,2)        null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table PDPASA_FNM_REGIONSUMMARY is
'PDPASA_FNM_REGIONSUMMARY shows the summary of PDPASA outcome for each region.';

comment on column PDPASA_FNM_REGIONSUMMARY.RUN_DATETIME is
'Unique Timestamp Identifier for this run, identified by the first half hour ended interval of the run';

comment on column PDPASA_FNM_REGIONSUMMARY.INTERVAL_DATETIME is
'End date time of the interval';

comment on column PDPASA_FNM_REGIONSUMMARY.REGIONID is
'Region identifier';

comment on column PDPASA_FNM_REGIONSUMMARY.LORCONDITION is
'Lack of Reserve Condition (LORCONDITION) > 0 if a supply deficit exists in the Zone for this Region that contains its Regional Reference Node
LORCONDITION indicates the most severe condition:
LORCONDITION = 3 if deficit in BASE run; else
LORCONDITION = 2 if deficit in RELIABILITY run; else
LORCONDITION = 1 if deficit in WARNING run';

comment on column PDPASA_FNM_REGIONSUMMARY.DEFICITCONDITION is
'Deficit Condition (DEFICITCONDITION) > 0 if a supply deficit only exists in a Zone for this Region that does not contain its Regional Reference Node DEFICITCONDITION indicates the most severe condition:
DEFICITCONDITION = 3 if deficit in BASE run; else
DEFICITCONDITION = 2 if deficit in RELIABILITY run; else
DEFICITCONDITION = 1 if deficit in WARNING run';

comment on column PDPASA_FNM_REGIONSUMMARY.DEMAND50 is
'50% Probability of Exceedance demand forecast (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.DEMAND50_UNSCHED_GEN is
'50% Probability of Exceedance demand forecast plus Aggregate Generation Forecast of all non-scheduled and exempt generation (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.SCHED_SS_GEN_CAPACITYAVAIL is
'Aggregate Bid MaxAvail of all scheduled generating units, scheduled bidirectional units (Gen side) and semi-scheduled generating units, with latter capped at UIGF (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.UNSCHED_GEN_CAPACITYAVAIL is
'Aggregate Generation Forecast of all non-scheduled and exempt generation (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.SCHED_SS_GEN_PASAAVAIL is
'Aggregate Bid PASAAvailability of all scheduled generating units and scheduled bidirectional units (Gen side) with a Bid Recall Period less than (Interval_DateTime minus Run_DateTime) plus UIGF for all semi-scheduled generating units (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.SCHED_LOAD_CAPACITYAVAIL is
'Aggregate Bid MaxAvail of all scheduled loads (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.SS_UIGF is
'Aggregate 50% Probability of Exceedance Unconstrained Intermittent Generation Forecast (UIGF) of all semi-scheduled generating units (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.SS_SOLAR_UIGF is
'Aggregate 50% Probability of Exceedance Unconstrained Intermittent Generation Forecast (UIGF) of all solar semi-scheduled generating units (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.SS_WIND_UIGF is
'Aggregate 50% Probability of Exceedance Unconstrained Intermittent Generation Forecast (UIGF) of all wind semi-scheduled generating units (MW)';

comment on column PDPASA_FNM_REGIONSUMMARY.LASTCHANGED is
'Date time this record was created';

alter table PDPASA_FNM_REGIONSUMMARY
   add constraint PDPASA_FNM_REGIONSUMMARY_PK primary key (RUN_DATETIME, INTERVAL_DATETIME, REGIONID);

