comment on column PEROFFER.PASAAVAILABILITY is
'The physical plant capability including any capability potentially available within 24 hours.';

comment on column PEROFFER.MR_CAPACITY is
'Mandatory Restriction Offer amount';

alter table PEROFFER
   add constraint PEROFFER_PK primary key (SETTLEMENTDATE, DUID, OFFERDATE, VERSIONNO, PERIODID);

