/*==============================================================*/
/* Table: PREDISPATCHCASESOLUTION                               */
/*==============================================================*/
create table PREDISPATCHCASESOLUTION (
   PREDISPATCHSEQNO     VARCHAR(20)          not null,
   RUNNO                NUMERIC(3,0)         not null,
   SOLUTIONSTATUS       NUMERIC(2,0)         null,
   SPDVERSION           VARCHAR(20)          null,
   NONPHYSICALLOSSES    NUMERIC(1,0)         null,
   TOTALOBJECTIVE       NUMERIC(27,10)       null,
   TOTALAREAGENVIOLATION NUMERIC(15,5)        null,
   TOTALINTERCONNECTORVIOLATION NUMERIC(15,5)        null,
   TOTALGENERICVIOLATION NUMERIC(15,5)        null,
   TOTALRAMPRATEVIOLATION NUMERIC(15,5)        null,
   TOTALUNITMWCAPACITYVIOLATION NUMERIC(15,5)        null,
   TOTAL5MINVIOLATION   NUMERIC(15,5)        null,
   TOTALREGVIOLATION    NUMERIC(15,5)        null,
   TOTAL6SECVIOLATION   NUMERIC(15,5)        null,
   TOTAL60SECVIOLATION  NUMERIC(15,5)        null,
   TOTALASPROFILEVIOLATION NUMERIC(15,5)        null,
   TOTALENERGYCONSTRVIOLATION NUMERIC(15,5)        null,
   TOTALENERGYOFFERVIOLATION NUMERIC(15,5)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   INTERVENTION         NUMERIC(2,0)         null
);

comment on table PREDISPATCHCASESOLUTION is
'PREDISPATCHCASESOLUTION provides information relating to the complete predispatch run. The fields provide an overview of the dispatch run results allowing immediate identification of conditions such as energy or FCAS deficiencies.';

comment on column PREDISPATCHCASESOLUTION.PREDISPATCHSEQNO is
'Unique identifier of predispatch run in the form YYYYMMDDPP with 01 at 04:30';

comment on column PREDISPATCHCASESOLUTION.RUNNO is
'Predispatch run no, normally 1.';

comment on column PREDISPATCHCASESOLUTION.SOLUTIONSTATUS is
'If non-zero indicated one of the following conditions: 1 = Supply Scarcity, Excess generation or constraint violations, -X = Model failure';

comment on column PREDISPATCHCASESOLUTION.SPDVERSION is
'Current version of SPD';

comment on column PREDISPATCHCASESOLUTION.NONPHYSICALLOSSES is
'Non-Physical Losses algorithm invoked during this run';

comment on column PREDISPATCHCASESOLUTION.TOTALOBJECTIVE is
'The Objective function from the LP';

comment on column PREDISPATCHCASESOLUTION.TOTALAREAGENVIOLATION is
'Total Region Demand violations';

comment on column PREDISPATCHCASESOLUTION.TOTALINTERCONNECTORVIOLATION is
'Total interconnector violations';

comment on column PREDISPATCHCASESOLUTION.TOTALGENERICVIOLATION is
'Total generic constraint violations';

comment on column PREDISPATCHCASESOLUTION.TOTALRAMPRATEVIOLATION is
'Total ramp rate violations';

comment on column PREDISPATCHCASESOLUTION.TOTALUNITMWCAPACITYVIOLATION is
'Total unit capacity violations';

comment on column PREDISPATCHCASESOLUTION.TOTAL5MINVIOLATION is
'Total of 5 minute ancillary service region violations';

comment on column PREDISPATCHCASESOLUTION.TOTALREGVIOLATION is
'Total of Regulation ancillary service region violations';

comment on column PREDISPATCHCASESOLUTION.TOTAL6SECVIOLATION is
'Total of 6 second ancillary service region violations';

comment on column PREDISPATCHCASESOLUTION.TOTAL60SECVIOLATION is
'Total of 60 second ancillary service region violations';

comment on column PREDISPATCHCASESOLUTION.TOTALASPROFILEVIOLATION is
'Total of ancillary service trader profile violations';

comment on column PREDISPATCHCASESOLUTION.TOTALENERGYCONSTRVIOLATION is
'Total of Energy Constrained unit offer violations.';

comment on column PREDISPATCHCASESOLUTION.TOTALENERGYOFFERVIOLATION is
'Total of unit summated offer band violations';

comment on column PREDISPATCHCASESOLUTION.LASTCHANGED is
'Last date and time record changed';

comment on column PREDISPATCHCASESOLUTION.INTERVENTION is
'Flag to indicate if this Pre-Dispatch case includes an intervention pricing run: 0 = case does not include an intervention pricing run, 1 = case does include an intervention pricing run. This field has a default value of 0 and is not nullable';

