create table PREDISPATCHINTERCONNECTORRES (
   PREDISPATCHSEQNO     VARCHAR(20)          null,
   RUNNO                NUMERIC(3,0)         null,
   INTERCONNECTORID     VARCHAR(10)          not null,
   PERIODID             VARCHAR(20)          null,
   INTERVENTION         NUMERIC(2,0)         null,
   METEREDMWFLOW        NUMERIC(15,5)        null,
   MWFLOW               NUMERIC(15,5)        null,
   MWLOSSES             NUMERIC(15,5)        null,
   MARGINALVALUE        NUMERIC(15,5)        null,
   VIOLATIONDEGREE      NUMERIC(15,5)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   DATETIME             TIMESTAMP(0)         not null,
   EXPORTLIMIT          NUMERIC(15,5)        null,
   IMPORTLIMIT          NUMERIC(15,5)        null,
   MARGINALLOSS         NUMERIC(15,5)        null,
   EXPORTGENCONID       VARCHAR(20)          null,
   IMPORTGENCONID       VARCHAR(20)          null,
   FCASEXPORTLIMIT      NUMERIC(15,5)        null,
   FCASIMPORTLIMIT      NUMERIC(15,5)        null,
   LOCAL_PRICE_ADJUSTMENT_EXPORT NUMERIC(10,2)        null,
   LOCALLY_CONSTRAINED_EXPORT NUMERIC(1,0)         null,
   LOCAL_PRICE_ADJUSTMENT_IMPORT NUMERIC(10,2)        null,
   LOCALLY_CONSTRAINED_IMPORT NUMERIC(1,0)         null
);

comment on table PREDISPATCHINTERCONNECTORRES is
'PREDISPATCHINTERCONNECTORRES records Interconnector flows and losses for the periods calculated in each predispatch run. Only binding and interconnector constraints are reported.
Some fields are for the Frequency Controlled Ancillary Services export and import limits and extra reporting of the generic constraint setting the energy import and export limits.';

comment on column PREDISPATCHINTERCONNECTORRES.PREDISPATCHSEQNO is
'Unique identifier of predispatch run in the form YYYYMMDDPP with 01 at 04:30';

comment on column PREDISPATCHINTERCONNECTORRES.RUNNO is
'SPD Predispatch run no, typically 1. It increments if the case is re-run.';

comment on column PREDISPATCHINTERCONNECTORRES.INTERCONNECTORID is
'Interconnector identifier';

comment on column PREDISPATCHINTERCONNECTORRES.PERIODID is
'PERIODID is just a period count, starting from 1 for each predispatch run. Use DATETIME to determine half hour period.';

comment on column PREDISPATCHINTERCONNECTORRES.INTERVENTION is
'Flag to indicate if this result set was sourced from the pricing run (INTERVENTION=0) or the physical run (INTERVENTION=1). In the event that there is not intervention in the market, both pricing and physical runs correspond to INTERVENTION=0';

comment on column PREDISPATCHINTERCONNECTORRES.METEREDMWFLOW is
'Metered MW Flow from EMS. For periods subsequent to the first period of a Pre-Dispatch run, this value represents the cleared target for the previous period of that Pre-Dispatch run.';

comment on column PREDISPATCHINTERCONNECTORRES.MWFLOW is
'Calculated MW Flow';

comment on column PREDISPATCHINTERCONNECTORRES.MWLOSSES is
'Calculated MW Losses';

comment on column PREDISPATCHINTERCONNECTORRES.MARGINALVALUE is
'$ Marginal value of interconnector constraint from SPD';

comment on column PREDISPATCHINTERCONNECTORRES.VIOLATIONDEGREE is
'Degree of violation of interconnector constraint in MW';

comment on column PREDISPATCHINTERCONNECTORRES.LASTCHANGED is
'Last changed.';

comment on column PREDISPATCHINTERCONNECTORRES.DATETIME is
'Period date and time';

comment on column PREDISPATCHINTERCONNECTORRES.EXPORTLIMIT is
'Calculated export limit.';

comment on column PREDISPATCHINTERCONNECTORRES.IMPORTLIMIT is
'Calculated import limit.';

comment on column PREDISPATCHINTERCONNECTORRES.MARGINALLOSS is
'Marginal loss factor. Use this to adjust bids between reports.';

comment on column PREDISPATCHINTERCONNECTORRES.EXPORTGENCONID is
'Generic Constraint setting the export limit';

comment on column PREDISPATCHINTERCONNECTORRES.IMPORTGENCONID is
'Generic Constraint setting the import limit';

comment on column PREDISPATCHINTERCONNECTORRES.FCASEXPORTLIMIT is
'Calculated export limit applying to energy + FCAS.';

comment on column PREDISPATCHINTERCONNECTORRES.FCASIMPORTLIMIT is
'Calculated import limit applying to energy + FCAS.';

comment on column PREDISPATCHINTERCONNECTORRES.LOCAL_PRICE_ADJUSTMENT_EXPORT is
'Aggregate Constraint contribution cost of this Interconnector: Sum(MarginalValue x Factor) for all relevant Constraints, for Export (Factor >= 0)';

comment on column PREDISPATCHINTERCONNECTORRES.LOCALLY_CONSTRAINED_EXPORT is
'Key for Local_Price_Adjustment_Export: 2 = at least one Outage Constraint; 1 = at least 1 System Normal Constraint (and no Outage Constraint); 0 = No System Normal or Outage Constraints';

comment on column PREDISPATCHINTERCONNECTORRES.LOCAL_PRICE_ADJUSTMENT_IMPORT is
'Aggregate Constraint contribution cost of this Interconnector: Sum(MarginalValue x Factor) for all relevant Constraints, for Import (Factor >= 0)';

comment on column PREDISPATCHINTERCONNECTORRES.LOCALLY_CONSTRAINED_IMPORT is
'Key for Local_Price_Adjustment_Import: 2 = at least one Outage Constraint; 1 = at least 1 System Normal Constraint (and no Outage Constraint); 0 = No System Normal or Outage Constraints';

alter table PREDISPATCHINTERCONNECTORRES
   add constraint PK_PREDISPATCHINTCONRES primary key (DATETIME, INTERCONNECTORID);

