   PERIODID             NUMERIC(10,0)        not null,
   PARTICIPANTID        VARCHAR(10)          not null,
   TCPID                VARCHAR(10)          not null,
   REGIONID             VARCHAR(10)          null,
   IGENERGY             NUMERIC(16,6)        null,
   XGENERGY             NUMERIC(16,6)        null,
   INENERGY             NUMERIC(16,6)        null,
   XNENERGY             NUMERIC(16,6)        null,
   IPOWER               NUMERIC(16,6)        null,
   XPOWER               NUMERIC(16,6)        null,
   RRP                  NUMERIC(20,5)        null,
   EEP                  NUMERIC(16,6)        null,
   TLF                  NUMERIC(7,5)         null,
   CPRRP                NUMERIC(16,6)        null,
   CPEEP                NUMERIC(16,6)        null,
   TA                   NUMERIC(16,6)        null,
   EP                   NUMERIC(16,6)        null,
   APC                  NUMERIC(16,6)        null,
   RESC                 NUMERIC(16,6)        null,
   RESP                 NUMERIC(16,6)        null,
   METERRUNNO           NUMERIC(10,0)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   HOSTDISTRIBUTOR      VARCHAR(10)          null,
   MDA                  VARCHAR(10)          not null,
   AFE                  NUMERIC(18,8)        null,
   DME                  NUMERIC(18,8)        null,
   UFEA                 NUMERIC(18,8)        null,
   AGE                  NUMERIC(18,8)        null,
   IMPORTENERGYCOST     NUMERIC(18,8)        null,
   EXPORTENERGYCOST     NUMERIC(18,8)        null
);

comment on table SETCPDATA is
'SETCPDATA shows meter settlement data for each connection point. This is the key view for retailers to verify energy charges. A regional summary view is also provided. As the view has values for each connection point by period, for each meter data file, it is a very large view. The table is populated for participants using Data Model 5.2. For participants using Data Model 5.3 or higher, SET_ENERGY_TRANSACTIONS and SET_ENERGY_GENSET_DETAIL replace SETCPDATA.';

comment on column SETCPDATA.SETTLEMENTDATE is
'Calendar Settlement Date';

comment on column SETCPDATA.VERSIONNO is
'Settlement run no';

comment on column SETCPDATA.PERIODID is
'Settlements Trading Interval.';

comment on column SETCPDATA.PARTICIPANTID is
'Unique participant identifier';

comment on column SETCPDATA.TCPID is
'Connection point identifier';

comment on column SETCPDATA.REGIONID is
'Region Identifier';

comment on column SETCPDATA.IGENERGY is
'Import Gross energy into the pool - MWh';

comment on column SETCPDATA.XGENERGY is
'Export Gross energy from the pool - MWh';

comment on column SETCPDATA.INENERGY is
'Import Nett energy into the pool - MWh, plus UFEA if the UFEA amount is positive. When GS commences, this includes the UFEA amount in the settlement runs.';

comment on column SETCPDATA.XNENERGY is
'Export Nett energy from the pool - MWh, plus (UFEA * -1) if the UFEA amount is negative. When GS commences, this includes the UFEA amount in the settlement runs.';

comment on column SETCPDATA.IPOWER is
'Import reactive power';

comment on column SETCPDATA.XPOWER is
'Export reactive power';

comment on column SETCPDATA.RRP is
'Regional Reference Price';

comment on column SETCPDATA.EEP is
'Excess Energy Price';

comment on column SETCPDATA.TLF is
'Transmission Loss Factor';

comment on column SETCPDATA.CPRRP is
'Connection Point Price = RRP * TLF';

comment on column SETCPDATA.CPEEP is
'Connection Point Excess Energy Price = EEP * TLF';

comment on column SETCPDATA.TA is
'Export - Import of Net energy (MWh)';

comment on column SETCPDATA.EP is
'settlement amount in $ for trading period';

comment on column SETCPDATA.APC is
'Not used';

comment on column SETCPDATA.RESC is
'Not used';

comment on column SETCPDATA.RESP is
'Not used';

comment on column SETCPDATA.METERRUNNO is
'Meter Run Number = version number of the meter file';

comment on column SETCPDATA.LASTCHANGED is
'Last date and time record changed';

comment on column SETCPDATA.HOSTDISTRIBUTOR is
'Not used';

comment on column SETCPDATA.MDA is
'Metering Data Agent';

comment on column SETCPDATA.AFE is
'Accounted For Energy for this Market Customer FRMP and TNI in the Settlements Trading Interval, excluding any UFEA component';

comment on column SETCPDATA.DME is
'Sum of ME- for all NMIs at this Market Customer FRMP and TNI in the Settlements Trading Interval.';

comment on column SETCPDATA.UFEA is
'Share of UFE allocated to this FRMP and TNI in the Settlements Trading Interval.';

comment on column SETCPDATA.AGE is
'Adjusted Gross Energy for this Market Customer FRMP and TNI in the Settlements Trading Interval. When GS commences, this includes the UFEA amount in the settlement runs.';

comment on column SETCPDATA.IMPORTENERGYCOST is
'The total cost of energy sold at the connection point by the participant in this settlement interval';

comment on column SETCPDATA.EXPORTENERGYCOST is
'The total cost of energy purchased at the connection point by the participant in this settlement interval';

alter table SETCPDATA
   add constraint SETCPDATA_PK primary key (SETTLEMENTDATE, VERSIONNO, PERIODID, PARTICIPANTID, TCPID, MDA);

