   FPP_ASOE_AMOUNT      NUMERIC(18,8)        null,
   FPP_RESIDUAL_AMOUNT  NUMERIC(18,8)        null,
   USED_ACE_AMOUNT      NUMERIC(18,8)        null,
   USED_ASOE_AMOUNT     NUMERIC(18,8)        null,
   USED_RESIDUAL_AMOUNT NUMERIC(18,8)        null,
   UNUSED_ACE_AMOUNT    NUMERIC(18,8)        null,
   UNUSED_ASOE_AMOUNT   NUMERIC(18,8)        null,
   UNUSED_RESIDUAL_AMOUNT NUMERIC(18,8)        null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table SET_FCAS_REG_RESIDAMT is
'This report contains the FCAS Regulation Residue Amounts that include FPP Residual Amounts, Used Residual Amounts and Unused Residual Amounts calculated using the Energy Ratio for each Requirement Region.';

comment on column SET_FCAS_REG_RESIDAMT.SETTLEMENTDATE is
'The Settlement Date of the Billing Week';

comment on column SET_FCAS_REG_RESIDAMT.VERSIONNO is
'The Settlement Run No';

comment on column SET_FCAS_REG_RESIDAMT.PARTICIPANTID is
'The Participant Id Identifier';

comment on column SET_FCAS_REG_RESIDAMT.CONSTRAINTID is
'The FCAS Regulation Constraint ID';

comment on column SET_FCAS_REG_RESIDAMT.PERIODID is
'The Period ID Identifier';

comment on column SET_FCAS_REG_RESIDAMT.REGIONID is
'The RegionId used for the residual calculation. This is the Constraint Requirement Region.';

comment on column SET_FCAS_REG_RESIDAMT.BIDTYPE is
'The BidType LOWERREG or RAISEREG for the Constraint ID';

comment on column SET_FCAS_REG_RESIDAMT.ACE_MWH is
'The ACE MWh value that is used for the Residual Calculation.(Excluding CPID with CF)';

comment on column SET_FCAS_REG_RESIDAMT.ASOE_MWH is
'The ASOE MWh value that is used for the FCAS Residual Calculation.(Excluding CPID with CF).';

comment on column SET_FCAS_REG_RESIDAMT.RESIDUAL_MWH is
'Sum of ABS(ACE_MWh) + ASOE_MWh. The MWh is not netted for residual calculation.';

comment on column SET_FCAS_REG_RESIDAMT.FPP_ACE_AMOUNT is
'The FPP ACE Amount calculated using the portion of ACE MWh value against the Total residual MWh of the requirement regions.';

comment on column SET_FCAS_REG_RESIDAMT.FPP_ASOE_AMOUNT is
'The FPP ASOE Amount calculated using the portion of ASOE MWh value against the Total residual MWh of the requirement regions.';

