   RECOVERY_AMOUNT_CUSTOMER NUMERIC(18,8)        null,
   RECOVERY_AMOUNT_GENERATOR NUMERIC(18,8)        null,
   PARTICIPANT_ACE_MWH  NUMERIC(18,8)        null,
   REGION_ACE_MWH       NUMERIC(18,8)        null,
   PARTICIPANT_ASOE_MWH NUMERIC(18,8)        null,
   REGION_ASOE_MWH      NUMERIC(18,8)        null,
   RECOVERYAMOUNT_ACE   NUMERIC(18,8)        null,
