comment on table SET_RECOVERY_ENERGY is
'Settlements substitution recovery energy used';

comment on column SET_RECOVERY_ENERGY.SETTLEMENTDATE is
'Settlement date';

comment on column SET_RECOVERY_ENERGY.SETTLEMENTRUNNO is
'Settlement run number';

comment on column SET_RECOVERY_ENERGY.PARTICIPANTID is
'Unique identifier for the participant';

comment on column SET_RECOVERY_ENERGY.REGIONID is
'Unique Identifier for the Region to which the TNI belongs on this settlement date';

