   WDRRR                NUMERIC(18,8)        null,
   RRP                  NUMERIC(18,8)        null,
   TLF                  NUMERIC(18,8)        null,
   ME_DLFADJUSTED       NUMERIC(18,8)        null,
   BQ_DLFADJUSTED       NUMERIC(18,8)        null,
