   PRUDENTIAL_DATE      TIMESTAMP(0)         not null,
   PRUDENTIAL_RUNNO     NUMERIC(8)           not null,
   PARTICIPANTID        VARCHAR(10)          not null,
   TRADING_LIMIT        NUMERIC(18,8)        null,
   PRUDENTIAL_EXPOSURE_AMOUNT NUMERIC(18,8)        null,
   TRADING_MARGIN       NUMERIC(18,8)        null
);

comment on table SRA_PRUDENTIAL_COMP_POSITION is
'The prudential position of each company at the date and time of a specific prudential run';

comment on column SRA_PRUDENTIAL_COMP_POSITION.PRUDENTIAL_DATE is
'The prudential date of the run.';

comment on column SRA_PRUDENTIAL_COMP_POSITION.PRUDENTIAL_RUNNO is
'The run number for the prudential date';

comment on column SRA_PRUDENTIAL_COMP_POSITION.PARTICIPANTID is
'Unique participant identifier';

comment on column SRA_PRUDENTIAL_COMP_POSITION.TRADING_LIMIT is
'The Trading Limit of the company at the time of the prudential run';

comment on column SRA_PRUDENTIAL_COMP_POSITION.PRUDENTIAL_EXPOSURE_AMOUNT is
'Current Prudential Exposure of the Auction Participant including Offers';

comment on column SRA_PRUDENTIAL_COMP_POSITION.TRADING_MARGIN is
'The amount of Trading Margin available to the Auction Participant to trade (including Offered Units and Cancelled Units). Equal to TRADING_LIMIT minus PRUDENTIAL_EXPOSURE_AMOUNT.';

alter table SRA_PRUDENTIAL_COMP_POSITION
   add constraint SRA_PRUDENTIAL_COMP_PK primary key (PRUDENTIAL_DATE, PRUDENTIAL_RUNNO, PARTICIPANTID);

/*==============================================================*/
/* Table: SRA_PRUDENTIAL_EXPOSURE                               */
/*==============================================================*/
create table SRA_PRUDENTIAL_EXPOSURE (
   PRUDENTIAL_DATE      TIMESTAMP(0)         not null,
   PRUDENTIAL_RUNNO     NUMERIC(8)           not null,
   PARTICIPANTID        VARCHAR(10)          not null,
   SRA_YEAR             NUMERIC(4)           not null,
   SRA_QUARTER          NUMERIC(3)           not null,
   INTERCONNECTORID     VARCHAR(10)          not null,
   FROMREGIONID         VARCHAR(10)          not null,
   MAX_TRANCHE          NUMERIC(2)           null,
   AUCTIONID            VARCHAR(30)          null,
   OFFER_SUBMISSIONTIME TIMESTAMP(0)         null,
   AVERAGE_PURCHASE_PRICE NUMERIC(18,8)        null,
   AVERAGE_CANCELLATION_PRICE NUMERIC(18,8)        null,
   CANCELLATION_VOLUME  NUMERIC(18,8)        null,
   TRADING_POSITION     NUMERIC(18,8)        null
);

comment on table SRA_PRUDENTIAL_EXPOSURE is
'Records details of the Prudential Exposure of an SRA Auction Participant';

comment on column SRA_PRUDENTIAL_EXPOSURE.PRUDENTIAL_DATE is
'The prudential date of the run.';

comment on column SRA_PRUDENTIAL_EXPOSURE.PRUDENTIAL_RUNNO is
'The run number for the prudential date.';

comment on column SRA_PRUDENTIAL_EXPOSURE.PARTICIPANTID is
'Unique participant identifier';

comment on column SRA_PRUDENTIAL_EXPOSURE.SRA_YEAR is
'AEMO Contract Year number starting the week beginning 1 January';

comment on column SRA_PRUDENTIAL_EXPOSURE.SRA_QUARTER is
'Contract Relevant Quarter';

comment on column SRA_PRUDENTIAL_EXPOSURE.INTERCONNECTORID is
'The identifier for the Directional Interconnector';

comment on column SRA_PRUDENTIAL_EXPOSURE.FROMREGIONID is
'The source Region identifier for the Directional Interconnector';

comment on column SRA_PRUDENTIAL_EXPOSURE.MAX_TRANCHE is
'The largest Tranche where the Unit was either sold or offered. Used in the calculation of the Average Purchase Price for the Trading Position of the Product. The most recent Tranche where Units were cancelled or offered (if the Offer is below the Average Purchase Price)';

comment on column SRA_PRUDENTIAL_EXPOSURE.AUCTIONID is
'Unique identifier for the Auction having the Offer. Has a null value when no Offer is made for the Relevant Quarter';

comment on column SRA_PRUDENTIAL_EXPOSURE.OFFER_SUBMISSIONTIME is
'Timestamp of the Offer File submitted by the Auction Participant. Has a null value when no Offer is made for the Relevant Quarter';

comment on column SRA_PRUDENTIAL_EXPOSURE.AVERAGE_PURCHASE_PRICE is
'Calculated Average Purchase Price for the Product';

comment on column SRA_PRUDENTIAL_EXPOSURE.AVERAGE_CANCELLATION_PRICE is
'Calculated average cancellation price for product.';

comment on column SRA_PRUDENTIAL_EXPOSURE.CANCELLATION_VOLUME is
'Calculated cancellation volume for product.';

comment on column SRA_PRUDENTIAL_EXPOSURE.TRADING_POSITION is
'Calculated trading position for product.';

alter table SRA_PRUDENTIAL_EXPOSURE
   add constraint SRA_PRUDENTIAL_EXPOSURE_PK primary key (PRUDENTIAL_DATE, PRUDENTIAL_RUNNO, PARTICIPANTID, SRA_YEAR, SRA_QUARTER, INTERCONNECTORID, FROMREGIONID);

