/*==============================================================*/
/* Table: SSM_CONTRACT_UNIT_AVAIL                               */
/*==============================================================*/
create table SSM_CONTRACT_UNIT_AVAIL (
   CONTRACT_ID          VARCHAR(20)          not null,
   DUID                 VARCHAR(20)          not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   VERSION_DATETIME     TIMESTAMP(0)         not null,
   AVAILABLE            NUMERIC(1,0)         null,
   UNIT_COUNT           NUMERIC(4,0)         null,
   ACTIVATION_LEAD_TIME NUMERIC(6,0)         null,
   MIN_DISPATCH_MW      NUMERIC(18,8)        null,
   MIN_ENABLEMENT_DURATION NUMERIC(6,0)         null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table SSM_CONTRACT_UNIT_AVAIL is
'The variable parameters associated to the Unit within an SSM Contract, allowing changes to the base contract values due to unit availabilities (e.g Maintenance, Outages).';

comment on column SSM_CONTRACT_UNIT_AVAIL.CONTRACT_ID is
'Unique Contract Identifier';

comment on column SSM_CONTRACT_UNIT_AVAIL.DUID is
'Dispatchable Unit Identifier';

comment on column SSM_CONTRACT_UNIT_AVAIL.INTERVAL_DATETIME is
'The starting Dispatch Interval for the availability change. This will be the active availability until the next INTERVAL_DATETIME record for this Contract and DUID.';

comment on column SSM_CONTRACT_UNIT_AVAIL.VERSION_DATETIME is
'Effective Date and Time of this record.';

comment on column SSM_CONTRACT_UNIT_AVAIL.AVAILABLE is
'Indicates if DUID is available for the INTERVAL_DATETIME (1 = True, 0 = False).';

comment on column SSM_CONTRACT_UNIT_AVAIL.UNIT_COUNT is
'Number of sub-units within a DUID that are available for enablement.';

comment on column SSM_CONTRACT_UNIT_AVAIL.ACTIVATION_LEAD_TIME is
'The expected maximum lead time for the system security service to be enabled from a non-operational state in minutes.';

comment on column SSM_CONTRACT_UNIT_AVAIL.MIN_DISPATCH_MW is
'Minimum Dispatch Target required for DUID to enable the contract.';

comment on column SSM_CONTRACT_UNIT_AVAIL.MIN_ENABLEMENT_DURATION is
'Minimum duration a unit must be active to enable the contract in minutes.';

comment on column SSM_CONTRACT_UNIT_AVAIL.LASTCHANGED is
'Last time record was changed';

alter table SSM_CONTRACT_UNIT_AVAIL
   add constraint SSM_CONTRACT_UNIT_AVAIL_PK primary key (CONTRACT_ID, DUID, INTERVAL_DATETIME, VERSION_DATETIME);

