'Last changed date';

alter table SSM_INDICATIVE_ROLL_DUID
   add constraint SSM_INDICATIVE_ROLL_DUID_PK primary key (VERSION_DATETIME, INTERVAL_DATETIME, DUID, CONTRACT_ID);

