comment on column SSM_INSTRUCTION.START_INTERVAL_DATETIME is
'The first Dispatch Interval of the enablement.';

comment on column SSM_INSTRUCTION.END_INTERVAL_DATETIME is
'The last Dispatch Interval of the enablement.';

comment on column SSM_INSTRUCTION.LASTCHANGED is
'Last time record was changed.';

alter table SSM_INSTRUCTION
   add constraint SSM_INSTRUCTION_PK primary key (INSTRUCTION_ID, VERSION_DATETIME);

