/*==============================================================*/
create table STATIONOWNER (
   EFFECTIVEDATE        TIMESTAMP(0)         not null,
   PARTICIPANTID        VARCHAR(10)          not null,
   STATIONID            VARCHAR(10)          not null,
   VERSIONNO            NUMERIC(3,0)         not null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table STATIONOWNER is
'STATIONOWNER sets out the owner details of each station.';

comment on column STATIONOWNER.EFFECTIVEDATE is
'Effective date of this record';

comment on column STATIONOWNER.PARTICIPANTID is
'Unique participant identifier';

comment on column STATIONOWNER.STATIONID is
'Station Identifier';

comment on column STATIONOWNER.VERSIONNO is
'Version no of record within the effective date';

comment on column STATIONOWNER.LASTCHANGED is
'Last date and time record changed';

alter table STATIONOWNER
   add constraint STATIONOWNER_PK primary key (PARTICIPANTID, EFFECTIVEDATE, VERSIONNO, STATIONID);

/*==============================================================*/
/* Index: STATIONOWNER_LCX                                      */
/*==============================================================*/
create  index STATIONOWNER_LCX on STATIONOWNER (
LASTCHANGED
);

/*==============================================================*/
/* Index: STATIONOWNER_NDX2                                     */
/*==============================================================*/
create  index STATIONOWNER_NDX2 on STATIONOWNER (
STATIONID,
EFFECTIVEDATE,
VERSIONNO
);

/*==============================================================*/
/* Index: STATIONOWNER_NDX3                                     */
/*==============================================================*/
create  index STATIONOWNER_NDX3 on STATIONOWNER (
PARTICIPANTID
);

/*==============================================================*/
/* Table: STATIONOWNERTRK                                       */
/*==============================================================*/
create table STATIONOWNERTRK (
   EFFECTIVEDATE        TIMESTAMP(0)         not null,
   PARTICIPANTID        VARCHAR(10)          not null,
   VERSIONNO            NUMERIC(3,0)         not null,
   AUTHORISEDBY         VARCHAR(15)          null,
   AUTHORISEDDATE       TIMESTAMP(0)         null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table STATIONOWNERTRK is
'STATIONOWNERTRK shows the tracking for the associated object STATIONOWNER. Together, STATIONOWNERTRK and STATIONOWNER sets out the owner details of each station.';

comment on column STATIONOWNERTRK.EFFECTIVEDATE is
'Effective date of this record';

comment on column STATIONOWNERTRK.PARTICIPANTID is
'Unique participant identifier';

comment on column STATIONOWNERTRK.VERSIONNO is
'Version no of record within the effective date';

comment on column STATIONOWNERTRK.AUTHORISEDBY is
'User authorising record';

comment on column STATIONOWNERTRK.AUTHORISEDDATE is
'Date record authorised';

comment on column STATIONOWNERTRK.LASTCHANGED is
'Last date and time record changed';

alter table STATIONOWNERTRK
   add constraint STATIONOWNERTRK_PK primary key (PARTICIPANTID, EFFECTIVEDATE, VERSIONNO);

/*==============================================================*/
/* Index: STATIONOWNERTRK_LCX                                   */
/*==============================================================*/
create  index STATIONOWNERTRK_LCX on STATIONOWNERTRK (
LASTCHANGED
);

/*==============================================================*/
/* Table: STPASA_CASESOLUTION                                   */
/*==============================================================*/
create table STPASA_CASESOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   PASAVERSION          VARCHAR(10)          null,
   RESERVECONDITION     NUMERIC(1,0)         null,
   LORCONDITION         NUMERIC(1,0)         null,
   CAPACITYOBJFUNCTION  NUMERIC(12,3)        null,
   CAPACITYOPTION       NUMERIC(12,3)        null,
   MAXSURPLUSRESERVEOPTION NUMERIC(12,3)        null,
   MAXSPARECAPACITYOPTION NUMERIC(12,3)        null,
   INTERCONNECTORFLOWPENALTY NUMERIC(12,3)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   RELIABILITYLRCDEMANDOPTION NUMERIC(12,3)        null,
   OUTAGELRCDEMANDOPTION NUMERIC(12,3)        null,
   LORDEMANDOPTION      NUMERIC(12,3)        null,
   RELIABILITYLRCCAPACITYOPTION VARCHAR(10)          null,
   OUTAGELRCCAPACITYOPTION VARCHAR(10)          null,
   LORCAPACITYOPTION    VARCHAR(10)          null,
   LORUIGFOPTION        NUMERIC(3,0)         null,
   RELIABILITYLRCUIGFOPTION NUMERIC(3,0)         null,
   OUTAGELRCUIGFOPTION  NUMERIC(3,0)         null
);

comment on table STPASA_CASESOLUTION is
'STPASA_CASESOLUTION holds one record containing results pertaining to each entire solution';

comment on column STPASA_CASESOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this study';

comment on column STPASA_CASESOLUTION.PASAVERSION is
'Version of the PASA solver used to solve this case';

comment on column STPASA_CASESOLUTION.RESERVECONDITION is
'Low Reserve Condition (LRC) flag for the case (1 - LRC in the case, 0 - No LRCs in the case) for capacity run';

comment on column STPASA_CASESOLUTION.LORCONDITION is
'Lack of Reserve Condition (LOR) flag for the case indicates the most severe condition in the case  (3 = LOR3, 2 = LOR2, 1 = LOR1, 0 = No LOR)';

comment on column STPASA_CASESOLUTION.CAPACITYOBJFUNCTION is
'Objective Function from the Capacity Adequacy run';

comment on column STPASA_CASESOLUTION.CAPACITYOPTION is
'Not populated as of 2005 End of Year Release; was the demand forecast used for capacity adequacy assessment. 0 if no assessment, 1 for 10%, 2 for 50%, 3 for 90%';

comment on column STPASA_CASESOLUTION.MAXSURPLUSRESERVEOPTION is
'Not populated as of 2005 End of Year Release; was the demand forecast used for assessment of Maximum surplus Reserve. 0 if no assessment, 1 for 10%, 2 for 50%, 3 for 90%';

comment on column STPASA_CASESOLUTION.MAXSPARECAPACITYOPTION is
'Not populated as of 2005 End of Year Release; was the demand forecast used for assessment of Maximum Spare Capacity. 0 if no assessment, 1 for 10%, 2 for 50%, 3 for 90%';

comment on column STPASA_CASESOLUTION.INTERCONNECTORFLOWPENALTY is
'The penalty for non-zero interconnector flow';

comment on column STPASA_CASESOLUTION.LASTCHANGED is
'Date and time the record was created or modified';

comment on column STPASA_CASESOLUTION.RELIABILITYLRCDEMANDOPTION is
'Specifies the Probability of Exceedence (POE) demand forecast for Reliability LRC assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)';

comment on column STPASA_CASESOLUTION.OUTAGELRCDEMANDOPTION is
'Specifies the Probability of Exceedence (POE) demand forecast for outage LRC assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)';

comment on column STPASA_CASESOLUTION.LORDEMANDOPTION is
'Specifies the Probability of Exceedence (POE) demand forecast for LOR assessment (0 if no assessment, 10 for 10%, 50 for 50%, 90 for 90%)';

comment on column STPASA_CASESOLUTION.RELIABILITYLRCCAPACITYOPTION is
'Generation Availability to be used in Reliability LRC run (either PASA or MARKET)';

comment on column STPASA_CASESOLUTION.OUTAGELRCCAPACITYOPTION is
'Generation Availability to be used in Outage LRC run (either PASA or MARKET)';

comment on column STPASA_CASESOLUTION.LORCAPACITYOPTION is
'Generation Availability to be used in LOR run (either PASA or MARKET)';

comment on column STPASA_CASESOLUTION.LORUIGFOPTION is
'UIGF POE forecast availability used for this option';

comment on column STPASA_CASESOLUTION.RELIABILITYLRCUIGFOPTION is
'UIGF POE forecast availability used for this option';

comment on column STPASA_CASESOLUTION.OUTAGELRCUIGFOPTION is
'UIGF POE forecast availability used for this option';

alter table STPASA_CASESOLUTION
   add constraint CASESOLUTION_PK primary key (RUN_DATETIME);

/*==============================================================*/
/* Index: STPASA_CASESOLUTION_LCX                               */
/*==============================================================*/
create  index STPASA_CASESOLUTION_LCX on STPASA_CASESOLUTION (
LASTCHANGED
);

/*==============================================================*/
/* Table: STPASA_CONSTRAINTSOLUTION                             */
/*==============================================================*/
create table STPASA_CONSTRAINTSOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   CONSTRAINTID         VARCHAR(20)          not null,
   CAPACITYRHS          NUMERIC(12,2)        null,
   CAPACITYMARGINALVALUE NUMERIC(12,2)        null,
   CAPACITYVIOLATIONDEGREE NUMERIC(12,2)        null,
   LASTCHANGED          TIMESTAMP(0)         null,
   RUNTYPE              VARCHAR(20)          not null default 'OUTAGE_LRC',
   STUDYREGIONID        VARCHAR(20)          not null default 'MARKET'
);

comment on table STPASA_CONSTRAINTSOLUTION is
'STPASA_CONSTRAINTSOLUTION shows binding and violated constraint results from the capacity evaluation, including the RHS value.';

comment on column STPASA_CONSTRAINTSOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this study';

comment on column STPASA_CONSTRAINTSOLUTION.INTERVAL_DATETIME is
'The unique identifier for the interval within this study';

comment on column STPASA_CONSTRAINTSOLUTION.CONSTRAINTID is
'Constraint identifier (synonymous with GenConID)';

comment on column STPASA_CONSTRAINTSOLUTION.CAPACITYRHS is
'The RHS value in the capacity evaluation.';

comment on column STPASA_CONSTRAINTSOLUTION.CAPACITYMARGINALVALUE is
'Capacity adequacy assessment marginal value, 0 if not binding';

comment on column STPASA_CONSTRAINTSOLUTION.CAPACITYVIOLATIONDEGREE is
'Capacity adequacy assessment violation degree for generic constraint; 0 if not violating';

comment on column STPASA_CONSTRAINTSOLUTION.LASTCHANGED is
'Last changed date of this record';

comment on column STPASA_CONSTRAINTSOLUTION.RUNTYPE is
'Type of run. Values are RELIABILITY_LRC, OUTAGE_LRC and LOR. Note that the STPASA RELIABILITY_LRC and OUTAGE_LRC Run Types are discontinued from 31 July 2025, with only the LOR Run Type reported.';

comment on column STPASA_CONSTRAINTSOLUTION.STUDYREGIONID is
'Primary Region for LP Solve (or MARKET if none).';

alter table STPASA_CONSTRAINTSOLUTION
   add constraint CONSTRAINTSOLUTION_PK primary key (RUN_DATETIME, RUNTYPE, INTERVAL_DATETIME, CONSTRAINTID, STUDYREGIONID);

/*==============================================================*/
/* Index: STPASA_CONSTRAINTSOLUTION_LCX                         */
/*==============================================================*/
create  index STPASA_CONSTRAINTSOLUTION_LCX on STPASA_CONSTRAINTSOLUTION (
LASTCHANGED
);

/*==============================================================*/
/* Table: STPASA_DUIDAVAILABILITY                               */
/*==============================================================*/
create table STPASA_DUIDAVAILABILITY (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   DUID                 VARCHAR(20)          not null,
   GENERATION_MAX_AVAILABILITY NUMERIC(12,6)        null,
   GENERATION_PASA_AVAILABILITY NUMERIC(12,0)        null,
   GENERATION_RECALL_PERIOD NUMERIC(8,3)         null,
   LOAD_MAX_AVAILABILITY NUMERIC(12,6)        null,
   LOAD_PASA_AVAILABILITY NUMERIC(12,0)        null,
   LOAD_RECALL_PERIOD   NUMERIC(8,3)         null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table STPASA_DUIDAVAILABILITY is
'This report delivers available capacity, PASA availability and given recall period for all scheduled resources. Note that for an MNSP, DUID = LINKID in the MNSP_INTERCONNECTOR table.';

comment on column STPASA_DUIDAVAILABILITY.RUN_DATETIME is
'STPASA run, identified by the nominal start time of the run.';

comment on column STPASA_DUIDAVAILABILITY.INTERVAL_DATETIME is
'Half hour ended interval';

comment on column STPASA_DUIDAVAILABILITY.DUID is
'NEM Dispatchable Unit Identifier';

comment on column STPASA_DUIDAVAILABILITY.GENERATION_MAX_AVAILABILITY is
'Available Capacity for a scheduled generating unit, semi-scheduled generating unit, BDU (Gen side), WDR or MNSP.';

comment on column STPASA_DUIDAVAILABILITY.GENERATION_PASA_AVAILABILITY is
'PASA Availability for a scheduled generating unit, BDU (Gen side), WDR or MNSP. Null for a semi-scheduled generating unit.';

comment on column STPASA_DUIDAVAILABILITY.GENERATION_RECALL_PERIOD is
'Recall Period associated with the PASA Availability for a scheduled generating unit, BDU (Gen side), WDR or MNSP. Null for a semi-scheduled generating unit.';

comment on column STPASA_DUIDAVAILABILITY.LOAD_MAX_AVAILABILITY is
'Available Capacity for a scheduled load or BDU(Load side).';

comment on column STPASA_DUIDAVAILABILITY.LOAD_PASA_AVAILABILITY is
'PASA Availability for a scheduled load or BDU(Load side).';

comment on column STPASA_DUIDAVAILABILITY.LOAD_RECALL_PERIOD is
'Recall Period associated with the PASA Availability for a scheduled load or BDU(Load side).';

comment on column STPASA_DUIDAVAILABILITY.LASTCHANGED is
'Report Creation Date Time.';

alter table STPASA_DUIDAVAILABILITY
   add constraint STPASA_DUIDAVAILABILITY_PK primary key (RUN_DATETIME, INTERVAL_DATETIME, DUID);

/*==============================================================*/
/* Table: STPASA_FNM_CASESOLUTION                               */
/*==============================================================*/
create table STPASA_FNM_CASESOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   LORCONDITION         NUMERIC(1,0)         null,
   DEFICITCONDITION     NUMERIC(1,0)         null,
   BASE_RUN_AVAILABLE   VARCHAR(10)          null,
   RELIABILITY_RUN_AVAILABLE VARCHAR(10)          null,
   WARNING_RUN_AVAILABLE VARCHAR(10)          null,
   PASAVERSION          VARCHAR(30)          null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table STPASA_FNM_CASESOLUTION is
'STPASA_FNM_CASESOLUTION shows the case run details, including the available run types, LOR and Deficit condition for each case.';

comment on column STPASA_FNM_CASESOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this run, identified by the first half hour ended interval of the run';

comment on column STPASA_FNM_CASESOLUTION.LORCONDITION is
'LORCONDITION is only set if supply deficit exists in a Zone that contains the Regional Reference Node
LORCONDITION indicates the most severe condition for the case:
LORCONDITION = 3 if deficit in BASE run, else = 2 if deficit in RELIABILITY run, else = 1 if deficit in WARNING run, else 0';

comment on column STPASA_FNM_CASESOLUTION.DEFICITCONDITION is
'DEFICITCONDITION is only set if supply deficit exists in a Zone that does NOT contain the Regional Reference Node
DEFICITCONDITION indicates the most severe condition for the case:
DEFICITCONDITION = 3 if deficit in BASE run, else = 2 if deficit in RELIABILITY run, else = 1 if deficit in WARNING run, else 0';

comment on column STPASA_FNM_CASESOLUTION.BASE_RUN_AVAILABLE is
'YES = Available, NO = Not Available';

comment on column STPASA_FNM_CASESOLUTION.RELIABILITY_RUN_AVAILABLE is
'YES = Available, NO = Not Available';

comment on column STPASA_FNM_CASESOLUTION.WARNING_RUN_AVAILABLE is
'YES = Available, NO = Not Available';

comment on column STPASA_FNM_CASESOLUTION.PASAVERSION is
'Version of the PASA solver used to solve this case';

comment on column STPASA_FNM_CASESOLUTION.LASTCHANGED is
'Date time this record was created';

alter table STPASA_FNM_CASESOLUTION
   add constraint STPASA_FNM_CASESOLUTION_PK primary key (RUN_DATETIME);

/*==============================================================*/
/* Table: STPASA_FNM_CONSTRAINTSOLUTION                         */
/*==============================================================*/
create table STPASA_FNM_CONSTRAINTSOLUTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   RUNTYPE              VARCHAR(20)          not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   CONSTRAINTID         VARCHAR(100)         not null,
   MARGINALVALUE        NUMERIC(20,5)        null,
   VIOLATIONDEGREE      NUMERIC(15,5)        null,
   LHS                  NUMERIC(15,5)        null,
   RHS                  NUMERIC(15,5)        null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table STPASA_FNM_CONSTRAINTSOLUTION is
'STPASA_FNM_CONSTRAINTSOLUTION shows the manual or thermal constraint (created by PASA), including marginal value, violation degree, LHS and RHS.';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.RUN_DATETIME is
'Unique Timestamp Identifier for this run, identified by the first half hour ended interval of the run';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.RUNTYPE is
'Run Type (BASE, RELIABILITY, WARNING)';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.INTERVAL_DATETIME is
'End date time of the interval';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.CONSTRAINTID is
'Constraint identifier, either manual constraint (synonymous with GenConID) or thermal constraint created by PASA with format ''BASE_<BranchName>'' or ''<ContingencyID>_<BranchName>''';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.MARGINALVALUE is
'Constraint Marginal Value ($/MW)';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.VIOLATIONDEGREE is
'Constraint Violation Degree (MW)';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.LHS is
'Constraint LHS (MW)';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.RHS is
'Constraint RHS (MW)';

comment on column STPASA_FNM_CONSTRAINTSOLUTION.LASTCHANGED is
'Date time this record was created';

alter table STPASA_FNM_CONSTRAINTSOLUTION
   add constraint STPASA_FNM_CONSTRAINTS_PK primary key (RUN_DATETIME, RUNTYPE, INTERVAL_DATETIME, CONSTRAINTID);

/*==============================================================*/
/* Table: STPASA_FNM_DUIDAVAILABILITY                           */
/*==============================================================*/
create table STPASA_FNM_DUIDAVAILABILITY (
   RUN_DATETIME         TIMESTAMP(0)         not null,
