   GENERATION_RECALL_PERIOD NUMERIC(8,3)         null,
   LOAD_MAX_AVAILABILITY NUMERIC(12,3)        null,
   LOAD_PASA_AVAILABILITY NUMERIC(12,3)        null,
   LOAD_RECALL_PERIOD   NUMERIC(8,3)         null,
   LASTCHANGED          TIMESTAMP(0)         null
);

comment on table STPASA_FNM_DUIDAVAILABILITY is
'STPASA_FNM_DUIDAVAILABILITY shows Available Capacity, PASA Availability and given Recall Period for all scheduled';

comment on column STPASA_FNM_DUIDAVAILABILITY.RUN_DATETIME is
'Unique Timestamp Identifier for this run, identified by the first half hour ended interval of the run';

comment on column STPASA_FNM_DUIDAVAILABILITY.INTERVAL_DATETIME is
'End date time of the interval';

comment on column STPASA_FNM_DUIDAVAILABILITY.DUID is
'NEM Dispatchable Unit Identifier';

comment on column STPASA_FNM_DUIDAVAILABILITY.BID_TRADINGDATE is
'Trading Date of the energy bid';

comment on column STPASA_FNM_DUIDAVAILABILITY.BID_OFFERDATETIME is
'Date Time that the energy bid was received';

comment on column STPASA_FNM_DUIDAVAILABILITY.GENERATION_MAX_AVAILABILITY is
'Available Capacity for a scheduled generating unit, semi-scheduled generating unit, BDU (Gen side), WDR or MNSP';

comment on column STPASA_FNM_DUIDAVAILABILITY.GENERATION_PASA_AVAILABILITY is
'PASA Availability for a scheduled generating unit, BDU (Gen side), WDR or MNSP. Null for a semi-scheduled generating unit (MW)';

comment on column STPASA_FNM_DUIDAVAILABILITY.GENERATION_RECALL_PERIOD is
'Recall Period associated with the PASA Availability for a scheduled generating unit, BDU (Gen side), WDR or MNSP. Null for a semi-scheduled generating unit (Hours)';

comment on column STPASA_FNM_DUIDAVAILABILITY.LOAD_MAX_AVAILABILITY is
'Available Capacity for a scheduled load or BDU (Load side) (MW)';

comment on column STPASA_FNM_DUIDAVAILABILITY.LOAD_PASA_AVAILABILITY is
'PASA Availability for a scheduled load or BDU (Load side) (MW)';

comment on column STPASA_FNM_DUIDAVAILABILITY.LOAD_RECALL_PERIOD is
'Recall Period associated with the PASA Availability for a scheduled load or BDU (Load side) (Hours)';

comment on column STPASA_FNM_DUIDAVAILABILITY.LASTCHANGED is
'Date time this record was created';

alter table STPASA_FNM_DUIDAVAILABILITY
   add constraint STPASA_FNM_DUIDAVAILABILITY_PK primary key (RUN_DATETIME, INTERVAL_DATETIME, DUID);

