   RUN_DATETIME         TIMESTAMP(0)         not null,
   RUNTYPE              VARCHAR(20)          not null,
   INTERVAL_DATETIME    TIMESTAMP(0)         not null,
   REGIONID             VARCHAR(20)          not null,
   LORCONDITION         NUMERIC(1,0)         null,
   DEFICITCONDITION     NUMERIC(1,0)         null,
   INITIALDEMAND        NUMERIC(12,2)        null,
   DEMAND_UNCERTAINTY_MARGIN NUMERIC(12,2)        null,
   SCHED_GEN_UNCERTAINTY_MARGIN NUMERIC(12,2)        null,
   VRE_GEN_UNCERTAINTY_MARGIN NUMERIC(12,2)        null,
   SCHED_GEN_AUX_LOAD   NUMERIC(12,2)        null,
   ENERGYUNCONSTRAINED_CLEARED NUMERIC(12,2)        null,
   ENERGYCONSTRAINED_CLEARED NUMERIC(12,2)        null,
   BDU_CLEARED          NUMERIC(12,2)        null,
   SS_CLEARED           NUMERIC(12,2)        null,
   SS_SOLAR_CLEARED     NUMERIC(12,2)        null,
   SS_WIND_CLEARED      NUMERIC(12,2)        null,
   SPARECAPACITY        NUMERIC(12,2)        null,
   CLEAREDSUPPLY        NUMERIC(12,2)        null,
   CLEAREDLOSSES        NUMERIC(12,2)        null,
