   NETINTERCHANGEUNDERSCARCITY NUMERIC(12,2)        null,
   SURPLUSCAPACITY      NUMERIC(12,2)        null,
   SURPLUSRESERVE       NUMERIC(12,2)        null,
   RESERVECONDITION     NUMERIC(1,0)         null,
