/*==============================================================*/
create table VOLTAGE_INSTRUCTION (
   RUN_DATETIME         TIMESTAMP(0)         not null,
   EMS_ID               VARCHAR(60)          not null,
   PARTICIPANTID        VARCHAR(20)          null,
   STATION_ID           VARCHAR(60)          null,
   DEVICE_ID            VARCHAR(60)          null,
   DEVICE_TYPE          VARCHAR(20)          null,
   CONTROL_TYPE         VARCHAR(20)          null,
   TARGET               NUMERIC(20,5)        null,
   CONFORMING           NUMERIC(1,0)         null,
   INSTRUCTION_SUMMARY  VARCHAR(400)         null,
   VERSION_DATETIME     TIMESTAMP(0)         not null,
   INSTRUCTION_SEQUENCE NUMERIC(4,0)         null,
   ADDITIONAL_NOTES     VARCHAR(60)          null
);

comment on table VOLTAGE_INSTRUCTION is
'Child record for Voltage Instructions (MVAr Dispatch)';

comment on column VOLTAGE_INSTRUCTION.RUN_DATETIME is
'MVAr Interval – a timestamp of when instructions issued';

comment on column VOLTAGE_INSTRUCTION.EMS_ID is
'The unique identifier for reference within AEMO –matches equipment names between NOS and EMS';

comment on column VOLTAGE_INSTRUCTION.PARTICIPANTID is
'The NEM id of the participant who owns the equipment';

comment on column VOLTAGE_INSTRUCTION.STATION_ID is
'The id of the station where the control equipment resides';

comment on column VOLTAGE_INSTRUCTION.DEVICE_ID is
'The company/participant preferred name of an equipment';

comment on column VOLTAGE_INSTRUCTION.DEVICE_TYPE is
'One of REACTOR, CAPACITOR, GEN, SVC, TRANS or GRPGEN but may be extended to other types';

comment on column VOLTAGE_INSTRUCTION.CONTROL_TYPE is
'One of VOLTAGE, TAP, MVAR, SWITCH or COMMIT but may be extended to other types';

comment on column VOLTAGE_INSTRUCTION.TARGET is
'Instruction for the device, for this interval null denotes no instruction';

comment on column VOLTAGE_INSTRUCTION.CONFORMING is
'[0,1] Denotes if the Device is currently conforming';

comment on column VOLTAGE_INSTRUCTION.INSTRUCTION_SUMMARY is
'Verbose summary of instruction';

comment on column VOLTAGE_INSTRUCTION.VERSION_DATETIME is
'Datetime the file was published by VDS - Versions differ from Run_DateTime only for Supplemental runs';

comment on column VOLTAGE_INSTRUCTION.INSTRUCTION_SEQUENCE is
'Order for execution of Instruction';

comment on column VOLTAGE_INSTRUCTION.ADDITIONAL_NOTES is
'Additional information pertaining to a particular instruction, e.g. Previously issued instruction revoked';

alter table VOLTAGE_INSTRUCTION
   add constraint VOLTAGE_INSTRUCTION_PK primary key (RUN_DATETIME, VERSION_DATETIME, EMS_ID);

