   SOLUTION_CATEGORY    VARCHAR(60)          null,
   SOLUTION_STATUS      VARCHAR(60)          null,
   OPERATING_MODE       VARCHAR(60)          null,
   OPERATING_STATUS     VARCHAR(100)         null,
   EST_EXPIRY           TIMESTAMP(0)         null,
   EST_NEXT_INSTRUCTION TIMESTAMP(0)         null
);

comment on table VOLTAGE_INSTRUCTION_TRK is
'Parent record for Voltage Instructions (MVAr Dispatch). ''SIGNAL'' records will have no children; ''INSTRUCTION'' records will have children';

